  "range_high": 0.97,
  "summary": [
    "Frontier is analyzed within a distressed ULCC reference class with a published ~45.7% bankruptcy probability over 24 months.",
    "Frontier's sizable near-term liquidity (~$874M) against 2026 debt maturities (~$303M) provides runway that dampens immediate default risk.",
    "Industry distress signals, including Spirit Airlines' bankruptcy and elevated 2025–2026 bankruptcies, raise contagion risk and underlying credit stress.",
    "Ongoing 2025 losses and cost-cutting actions contribute to bankruptcy risk, but no filing has occurred yet, keeping risk elevated but not certain before May 1, 2026."
  ],
  "confidence": "high",
  "narrative": "Anchored in ULCC distress evidence with a ~45.7% 24-month bankruptcy probability, Frontier's liquidity cushion and 2026 maturities mitigate near-term risk while sector distress and ongoing losses push the probability higher. The calibrated posterior reaches 89% with caveats for evolving liquidity, sector dynamics, and potential mitigants, yielding a non-trivial but not imminent risk before May 1, 2026.",
  "justification": {
    "anchor": {
      "probability": 0.4574,
      "basis": "Reference class anchored to US ULCC distress with Altman Z-score in the distress zone; forecast evidence shows ~45.7% bankruptcy probability over the next 24 months."
    },
    "factor_updates": [
      {
        "factor": "Near-term debt maturities in 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "About $303 million of principal is due in 2026, creating refinancing pressure if liquidity wanes."
      },
      {
        "factor": "Total available liquidity as of 12/31/2025",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Frontier reports roughly $874 million of total liquidity, which helps cover near-term obligations but remains tight against sizable debt service and leases."
      },
      {
        "factor": "Industry distress from Spirit Airlines bankruptcy and sector pressures",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Spirit’s bankruptcy proceedings and going-concern signs add sector-wide credit and demand risks that can spill over to Frontier."
      },
      {
        "factor": "Frontier 2025 profitability trajectory (net loss)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A full-year 2025 net loss signals continued earnings pressure that can elevate bankruptcy risk under stressed conditions."
      },
      {
        "factor": "Fleet/capex adjustments (delivery deferrals and early returns with cost savings)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Non-binding fleet adjustments aim to cut near-term capital outlays and improve liquidity by reducing near-term cash burn."
      },
      {
        "factor": "Broader 2025–2026 US corporate bankruptcy surge",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A rising tempo of bankruptcies and elevated credit stress in 2025–2026 raises the base risk environment for distressed ULCCs like Frontier."
      }
    ],
    "synthesis_rationale": "Starting from a 0.4574 anchor, proximate risk-increasing factors (debt maturities, sector distress, macro bankruptcy momentum, ongoing losses) push probability upward, while the liquidity cushion and fleet-cost actions provide mitigations. The combination yields a calibrated posterior of 0.89, reflecting a high but not absolute risk; correlations among factors and sector dynamics were treated conservatively to avoid double-counting."
  }
}

